[data-parallax-move].--zk-shift:
calc(
          var(--zk-depth, 0) *
            var(
              --zk-parallax-amplitude,
              min(calc(var(--zk-reveal-distance, 0.75rem) * 8), var(--zk-parallax-max-shift, 120px))
            ) * var(--zk-motion-intensity, 1) * var(--zk-motion-mobile, 1)
        )

[data-parallax][data-parallax-axis=\"x\".--zk-shift:
calc(
          var(--zk-depth, 0) *
            var(
              --zk-parallax-amplitude-x,
              min(calc(var(--zk-reveal-distance, 0.75rem) * 8), var(--zk-parallax-max-shift, 12vw))
            ) * var(--zk-motion-intensity, 1) * var(--zk-motion-mobile, 1) * var(--zk-dir, 1)
        )

